from ore_algebra import *
from ore_algebra import guess

# ===== Sequences =====
N = _sage_const_100 

# AESZ inner sum
inner = []
for nn in range(N):
    inner.append(sum(binomial(nn,k)**_sage_const_2  * binomial(nn+k,nn) * binomial(nn+_sage_const_2 *k,nn) for k in range(nn+_sage_const_1 )))

# P2.7 sequence
def A_p(nn):
    nn = QQ(nn)
    return QQ(_sage_const_1024 )*(_sage_const_2 *nn+_sage_const_5 )**_sage_const_4 *(_sage_const_2 *nn+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *nn+_sage_const_9 )**_sage_const_3 *(_sage_const_946 *nn**_sage_const_2 +_sage_const_6407 *nn+_sage_const_10860 )
def B_p(nn):
    nn = QQ(nn)
    return QQ(_sage_const_128 )*(_sage_const_2 *nn+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *nn+_sage_const_9 )**_sage_const_3 *(_sage_const_104060 *nn**_sage_const_6 +_sage_const_1745370 *nn**_sage_const_5 +_sage_const_12145238 *nn**_sage_const_4 +_sage_const_44886481 *nn**_sage_const_3 +_sage_const_92943995 *nn**_sage_const_2 +_sage_const_102256019 *nn+_sage_const_46709052 )
def C_p(nn):
    nn = QQ(nn)
    return QQ(_sage_const_16 )*(nn+_sage_const_3 )**_sage_const_4 *(_sage_const_2 *nn+_sage_const_9 )**_sage_const_3 *(_sage_const_3784 *nn**_sage_const_5 +_sage_const_57792 *nn**_sage_const_4 +_sage_const_351019 *nn**_sage_const_3 +_sage_const_1059230 *nn**_sage_const_2 +_sage_const_1587211 *nn+_sage_const_944620 )
def D_p(nn):
    nn = QQ(nn)
    return (nn+_sage_const_3 )**_sage_const_4 *(nn+_sage_const_4 )**_sage_const_6 *(_sage_const_946 *nn**_sage_const_2 +_sage_const_4515 *nn+_sage_const_5399 )

q27 = [QQ(-_sage_const_215040420000 ), QQ(-_sage_const_167282265043404 )/_sage_const_905 , QQ(-_sage_const_964185327658080 )/_sage_const_6071 ]
for nn in range(_sage_const_2 , N):
    q27.append(B_p(nn)/A_p(nn)*q27[nn] - C_p(nn-_sage_const_1 )/A_p(nn-_sage_const_1 )*q27[nn-_sage_const_1 ] + D_p(nn-_sage_const_2 )/A_p(nn-_sage_const_2 )*q27[nn-_sage_const_2 ])

# ===== Guess ODEs =====
R = PolynomialRing(QQ, names=('z',)); (z,) = R._first_ngens(1)
D = OreAlgebra(R, names=('Dz',)); (Dz,) = D._first_ngens(1)

print("Guessing ODE for AESZ inner OGF A(z) = Σ a_n z^n...")
# The ODE should have order 6 (= degree of recurrence) and degree 3 (= order of recurrence)
# Actually: order-3 recurrence with degree-6 coefficients -> ODE of order ≤ 6 with degree ≤ 3
for ord in range(_sage_const_3 , _sage_const_10 ):
    try:
        L_a = guess(inner[:N], D, order=ord)
        deg = max(c.degree() for c in L_a.list())
        print(f"  order={ord}: degree={deg}")
        break
    except:
        print(f"  order={ord}: no")

print(f"\nGuessing ODE for P2.7 OGF Q(z) = Σ q_n z^n...")
# Expected: order ≤ 18, degree ≤ 3
for ord in range(_sage_const_3 , _sage_const_22 ):
    try:
        L_q = guess([QQ(x) for x in q27[:N]], D, order=ord)
        deg = max(c.degree() for c in L_q.list())
        print(f"  order={ord}: degree={deg}")
        break
    except:
        if ord % _sage_const_3  == _sage_const_0 :
            print(f"  order={ord}: no")

# ===== Also try: 64-gauged AESZ =====
v_seq = [inner[nn] / QQ(_sage_const_64 )**nn for nn in range(N)]
print(f"\nGuessing ODE for v(z) = Σ (a_n/64^n) z^n...")
for ord in range(_sage_const_3 , _sage_const_10 ):
    try:
        L_v = guess(v_seq[:N], D, order=ord)
        deg = max(c.degree() for c in L_v.list())
        print(f"  order={ord}: degree={deg}")
        break
    except:
        print(f"  order={ord}: no")

# ===== GCRD at ODE level =====
print(f"\n{'='*_sage_const_60 }")
